,p_process_name=>'PREFETCH_WBS_LIST'
,p_static_id=>'prefetch-wbs-list'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'begin',
'  apex_json.open_array;',
'  for r in (',
'    select id, nomor_laporan, tindakan, nama_pelapor, status, last_update_date',
'    from xtd_wbs',
'    order by last_update_date desc nulls last, id desc',
'    fetch first 9 rows only',
'  ) loop',
'    apex_json.open_object;',
'    apex_json.write(''id'', r.id);',
'    apex_json.write(''nomor_laporan'', r.nomor_laporan);',
'    apex_json.write(''tindakan'', r.tindakan);',
'    apex_json.write(''nama_pelapor'', r.nama_pelapor);',
'    apex_json.write(''status'', r.status);',
'    apex_json.write(''last_update_date'', to_char(r.last_update_date, ''YYYY-MM-DD"T"HH24:MI:SS''));',
'    apex_json.close_object;',
'  end loop;',
'  apex_json.close_array;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>31232390668719837342
,p_created_on=>wwv_flow_imp.dz('20260826042547Z')
