,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Tindakan'
,p_static_id=>'process-form-tindakan'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P3_TINDAKAN != ''USULAN/MASUKAN'' THEN',
'    UPDATE XTD_WBS ',
'    SET TINDAKAN = :P3_TINDAKAN',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P3_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P3_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P3_WAKTU_KEJADIAN);',
'END IF;',
'',
'IF :P3_TINDAKAN = ''USULAN/MASUKAN'' THEN',
'    UPDATE XTD_WBS ',
'    SET TINDAKAN = :P3_LAINNYA',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P3_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P3_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P3_WAKTU_KEJADIAN);',
'END IF;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>28174756776133630
);
