,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload File Attachment'
,p_static_id=>'upload-file-attachment'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_id number;',
'   l_file_names apex_t_varchar2;',
'   l_file apex_application_temp_files%rowtype;',
'BEGIN',
'   l_file_names := apex_string.split (',
'      p_str => :P3_UPLOAD,',
'      p_sep => '':''',
'   );',
'   ',
'   FOR i IN 1 .. l_file_names.count LOOP',
'      SELECT *',
'      INTO l_file',
'      FROM apex_application_temp_files',
'      WHERE name = l_file_names(i);',
'',
'      UPDATE XTD_WBS',
'      SET',
'         FILE_NAME = l_file.filename,',
'         MIME_TYPE = l_file.mime_type,',
'         FILE_BLOB = l_file.blob_content',
'      WHERE ID = (',
'         SELECT MAX(ID)',
'         FROM XTD_WBS',
'         WHERE EMAIL_PELAPOR = :P3_EMAIL_PELAPOR',
'         AND NAMA_TERLAPOR = :P3_NAMA_TERLAPOR',
'         AND WAKTU_KEJADIAN = :P3_WAKTU_KEJADIAN',
'      );',
'   END LOOP;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_required_patch=>wwv_flow_imp.id(161539204971679523752)
,p_internal_uid=>29147983857332201
);
