,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload File to WBS_BLOB'
,p_static_id=>'upload-file-to-wbs-blob'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    for c1 in (select *',
'               from apex_application_temp_files',
'               where name = :P3_UPLOAD)',
'    loop',
'        insert into XTD_WBS_BLOB (',
'            wbs_id,',
'            file_name,',
'            file_blob,',
'            file_mime_type)',
'        values (',
'            :P3_ID,',
'            c1.filename,',
'            c1.blob_content,',
'            c1.mime_type);',
'    end loop;',
'',
'    :P3_UPLOAD  := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_required_patch=>wwv_flow_imp.id(161539204971679523752)
