,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload File to XTD_WBS'
,p_static_id=>'upload-file-to-xtd-wbs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_wbs_id number; -- Sesuaikan tipe data dengan ID pada tabel XTD_WBS',
'BEGIN',
'   -- Ambil ID yang baru ditambahkan dari XTD_WBS_BLOB',
'   SELECT MAX(ID)',
'   INTO l_wbs_id',
'   FROM XTD_WBS_BLOB',
'   WHERE WBS_ID = :P3_ID; -- Sesuaikan dengan kondisi yang sesuai',
'',
'   -- Perbarui atau sisipkan ke dalam tabel XTD_WBS',
'   UPDATE XTD_WBS',
'   SET',
'      FILE_NAME = (SELECT FILE_NAME FROM XTD_WBS_BLOB WHERE ID = l_wbs_id),',
'      MIME_TYPE = (SELECT FILE_MIME_TYPE FROM XTD_WBS_BLOB WHERE ID = l_wbs_id),',
'      FILE_BLOB = (SELECT FILE_BLOB FROM XTD_WBS_BLOB WHERE ID = l_wbs_id)',
'   WHERE ID = :P3_ID;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_required_patch=>wwv_flow_imp.id(161539204971679523752)
,p_internal_uid=>29427657242845407
);
