,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_id number; ',
'   l_file_names apex_t_varchar2;',
'   l_file apex_application_temp_files%rowtype;',
'BEGIN',
'   l_file_names := apex_string.split (',
'      p_str => :P3_UPLOAD,',
'      p_sep => '':''',
'   );',
'',
'   FOR i IN 1 .. l_file_names.count LOOP',
'      SELECT *',
'      INTO l_file',
'      FROM apex_application_temp_files',
'      WHERE name = l_file_names(i);',
'',
'      INSERT INTO XTD_WBS_BLOB (',
'         FILE_NAME,',
'         FILE_MIME_TYPE,',
'         FILE_BLOB_DATED,',
'         FILE_BLOB,',
'         WBS_ID',
'      ) VALUES (',
'         l_file.filename,',
'         l_file.mime_type,',
'         SYSDATE, -- or use the appropriate date value',
'         l_file.blob_content,',
'         :P3_ID -- set WBS_ID accordingly',
'      );',
'   END LOOP;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
