,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form WBS Status (Admin Page Update)_1'
,p_static_id=>'process-form-wbs-status-admin-page-update-2'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P7_STATUS = ''SUBMITTED'' THEN',
'    UPDATE XTD_WBS ',
'    SET STATUS = :P7_STATUS',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'IF :P7_STATUS = ''REJECTED'' THEN',
'    UPDATE XTD_WBS ',
'    SET STATUS = :P7_STATUS',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'IF :P7_STATUS = ''ON PROGRESS'' THEN',
'    UPDATE XTD_WBS ',
'    SET STATUS = :P7_STATUS',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'IF :P7_STATUS = ''COMPLETED'' THEN',
'    UPDATE XTD_WBS ',
'    SET STATUS = :P7_STATUS',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'IF :P7_STATUS = ''ACCEPTED'' THEN',
'    UPDATE XTD_WBS ',
'    SET STATUS = :P7_STATUS',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'-----------------------',
'',
'IF :P7_PIC = ''LEGAL'' THEN',
'    UPDATE XTD_WBS ',
'    SET PIC = :P7_PIC',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'IF :P7_PIC = ''INTERNAL AUDIT'' THEN',
'    UPDATE XTD_WBS ',
'    SET PIC = :P7_PIC',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'IF :P7_PIC = ''HUMAN RESOURCES'' THEN',
'    UPDATE XTD_WBS ',
'    SET PIC = :P7_PIC',
'    WHERE ID = (SELECT MAX(ID) FROM XTD_WBS WHERE EMAIL_PELAPOR = :P7_EMAIL_PELAPOR AND NAMA_TERLAPOR = :P7_NAMA_TERLAPOR AND WAKTU_KEJADIAN = :P7_WAKTU_KEJADIAN);',
'END IF;',
'',
'COMMIT;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>29148044276332202
);
