wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(161565377802032130344)
,p_name=>'P9_TINDAKAN'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(161565374856933130334)
,p_item_source_plug_id=>wwv_flow_imp.id(161565374856933130334)
,p_prompt=>'Tindakan / Perbuatan yang  Dilaporkan'
,p_source=>'TINDAKAN'
,p_display_as=>'NATIVE_RADIOGROUP'
,p_lov=>'STATIC2:FRAUD;FRAUD,PELANGGARAN KODE ETIK;PELANGGARAN KODE ETIK,PELANGGARAN BENTURAN KEPENTINGAN;PELANGGARAN BENTURAN KEPENTINGAN,PELANGGARAN HUKUM;PELANGGARAN HUKUM,LAINNYA (SILAKAN DIISI SESUAI ADUAN);LAINNYA'
,p_field_template=>wwv_flow_imp.id(161539580904163523826)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<hr />',
'<p class="a-text a-text-body a-text-brownish-grey"><strong>FRAUD</strong></p>',
'<hr />',
'<p class="a-text a-text-body a-text-brownish-grey" align="justify">Tindakan penyimpangan atau pembiaran yang disengaja dilakukan untuk mengelabui, menipu, atau memanipulasi pihak lain, yang terjadi di lingkungan perusahaan dan/atau menggunakan sarana'
||' perusahaan sehingga mengakibatkan perusahaan menderita kerugian baik materiil maupun non materiil dan/atau pelaku fraud memperoleh keuntungan keuangan baik secara langsung maupun tidak langsung.</p>',
'<p class="a-text a-text-body a-text-brownish-grey" align="justify">Jenis-jenis perbuatan yang tergolong fraud adalah:</p>',
'<ul>',
'<li>Kecurangan,</li>',
'<li>Penipuan,</li>',
'<li>Penggelapan aset,</li>',
'<li>Pembocoran informasi</li>',
'</ul>',
'<hr />',
'<p><strong>PELANGGARAN KODE ETIK</strong></p>',
'<hr />',
'<p align="justify"><span>Tindakan yang tidak sesuai dengan budaya perusahaan yang telah dirumuskan berdasarkan nilai-nilai positif yang tumbuh dan berkembang di dalam diri segenap insan perusahaan, untuk mencapai tujuan bersama dan juga sebagai acuan'
||' bagi insan perusahaan dalam mengambil keputusan dan bertindak.</span></p>',
'<p><span></span></p>',
'<hr />',
'<p><strong>PELANGGARAN BENTURAN KEPENTINGAN</strong></p>',
'<hr />',
'<p align="justify"><span>Tindakan yang menyebabkan suatu kondisi di mana seseorang dalam menjalankan tugas dan kewajibannya mempunyai kepentingan di luar kepentingan dinas, baik yang menyangkut kepentingan pribadi, keluarga, maupun kepentingan pihak-'
||'pihak lain sehingga insan perusahaan tersebut dimungkinkan kehilangan obyektivitasnya dalam mengambil keputusan dan kebijakan sesuai wewenang yang telah diberikan perusahaan kepadanya.</span></p>',
'<p><span></span></p>',
'<hr />',
'<p><strong>PELANGGARAN HUKUM</strong></p>',
'<hr />',
'<p align="justify"><span>Tindakan yang melanggar hukum yang berlaku di Indonesia.</span></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '2',
  'page_action_on_selection', 'NONE')).to_clob
);
