,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Form Submitted'
,p_static_id=>'form-submitted'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_id NUMBER; ',
'    l_original_filename VARCHAR(255);',
'begin ',
'    l_id := apex_mail.send (',
'        p_to                 => :P9_EMAIL_PELAPOR,',
'        p_from               => ''SIPP.WBS@limamail.net'', --add by iwanhe',
'        p_template_static_id => ''FORM_SUBMITTED'',',
'        p_placeholders       => ''{'' ||',
'        ''    "NOMOR_LAPORAN":''    || apex_json.stringify( :P9_NOMOR_LAPORAN ) ||',
'        ''   ,"NAMA_PELAPOR":''        || apex_json.stringify( :P9_NAMA_PELAPOR ) ||',
'        ''   ,"EMAIL_PELAPOR":''       || apex_json.stringify( :P9_EMAIL_PELAPOR ) ||',
'        ''   ,"TELP_PELAPOR":''        || apex_json.stringify( :P9_TELP_PELAPOR ) ||',
'        ''   ,"TINDAKAN":''            || apex_json.stringify( :P9_TINDAKAN ) ||',
'        ''   ,"NAMA_TERLAPOR":''       || apex_json.stringify( :P9_NAMA_TERLAPOR ) ||',
'        ''   ,"JABATAN_TERLAPOR":''    || apex_json.stringify( :P9_JABATAN_TERLAPOR ) ||',
'        ''   ,"WAKTU_KEJADIAN":''      || apex_json.stringify( :P9_WAKTU_KEJADIAN ) ||',
'        ''   ,"LOKASI_KEJADIAN":''     || apex_json.stringify( :P9_LOKASI_KEJADIAN ) ||',
'        ''   ,"KRONOLOGIS_KEJADIAN":'' || apex_json.stringify( :P9_KRONOLOGIS_KEJADIAN ) ||',
'        ''   ,"NOMINAL":''             || apex_json.stringify( :P9_NOMINAL ) ||',
'        ''   ,"FILE":''                || apex_json.stringify( :P9_UPLOAD ) ||',
'        ''}'' );',
'        ',
'    FOR c1 IN (SELECT filename, blob_content, mime_type ',
'        FROM APEX_APPLICATION_TEMP_FILES) LOOP',
'',
'        BEGIN ',
'        SELECT SUBSTR(c1.filename, INSTR(c1.filename, ''/'', -1) + 1) INTO l_original_filename',
'            FROM dual;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                l_original_filename := c1.filename;',
'        END;',
'',
'        APEX_MAIL.ADD_ATTACHMENT(',
'            p_mail_id    => l_id,',
'            p_attachment => c1.blob_content,',
'            p_filename   => l_original_filename,',
'            p_mime_type  => c1.mime_type);',
